import java.io.*;

public class Main {

    static int[] s;   // digitos de entrada
    static int[] cur; // buffer do numero corrente
    static int n;

    // Tenta A = primeiros L digitos; verifica se S = str(A)||str(A+1)||...||str(B)
    static boolean check(int L) {
        if (s[0] == 0) return false; // A nao pode ter zero a esquerda
        System.arraycopy(s, 0, cur, 0, L);
        int curLen = L;
        int pos = L;
        while (pos < n) {
            // incrementa o numero atual (cur) em 1
            int i = curLen - 1;
            while (i >= 0 && cur[i] == 9) {
                cur[i] = 0;
                i--;
            }
            int nextLen;
            if (i >= 0) {
                cur[i]++;
                nextLen = curLen;
            } else {
                // overflow: ex. 999 -> 1000 (tamanho aumenta em 1)
                nextLen = curLen + 1;
                cur[0] = 1;
                cur[curLen] = 0;
            }
            if (n - pos < nextLen) return false;
            for (int j = 0; j < nextLen; j++) {
                if (s[pos + j] != cur[j]) return false;
            }
            pos += nextLen;
            curLen = nextLen;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        InputStreamReader isr = new InputStreamReader(System.in);
        StringBuilder input = new StringBuilder();
        char[] buf = new char[8192];
        int r;
        while ((r = isr.read(buf)) != -1) {
            input.append(buf, 0, r);
        }
        String text = input.toString();
        int tlen = text.length();

        // le N (primeiro numero da entrada)
        int idx = 0;
        while (idx < tlen && (text.charAt(idx) < '0' || text.charAt(idx) > '9')) idx++;
        n = 0;
        while (idx < tlen && text.charAt(idx) >= '0' && text.charAt(idx) <= '9') {
            n = n * 10 + (text.charAt(idx) - '0');
            idx++;
        }

        // coleta os N digitos (ignorando separadores)
        s = new int[n];
        cur = new int[n + 2];
        int cnt = 0;
        while (cnt < n && idx < tlen) {
            char ch = text.charAt(idx++);
            if (ch >= '0' && ch <= '9') {
                s[cnt++] = ch - '0';
            }
        }

        // A deve ser um prefixo de S; menor A = primeiro prefixo (menor comprimento)
        // cuja decomposicao em inteiros consecutivos consome exatamente S.
        for (int L = 1; L <= n; L++) {
            if (check(L)) {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < L; i++) sb.append((char) ('0' + s[i]));
                System.out.println(sb);
                return;
            }
        }
        // Nao deve acontecer para entradas validas
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append((char) ('0' + s[i]));
        System.out.println(sb);
    }
}
